import type { Metadata } from 'next'
import { Kanit } from 'next/font/google'
import './globals.css'
import ColorBends from '@/components/ColorBends'
import { site } from '@/content'
import { FULL_NAME, PERSON_JSON_LD, SITE_URL } from './site'

const kanit = Kanit({
  weight: ['300', '400', '500', '600', '700', '800', '900'],
  subsets: ['latin'],
  display: 'swap',
})

// The share card is generated by app/opengraph-image.tsx — Next.js adds it to both tags below
export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: site.title,
  description: site.description,
  authors: [{ name: FULL_NAME, url: SITE_URL }],
  keywords: site.keywords,
  alternates: { canonical: '/' },
  openGraph: {
    type: 'website',
    url: '/',
    siteName: FULL_NAME,
    title: site.title,
    description: site.description,
    locale: site.locale,
  },
  twitter: {
    card: 'summary_large_image',
    title: site.title,
    description: site.description,
  },
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang={site.locale.split('_')[0]} className={kanit.className}>
      <body className="relative bg-[#03010A]">
        {/* Tells search engines who the page is about */}
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(PERSON_JSON_LD) }}
        />
        {/* Persistent full-page animated background */}
        <div className="fixed inset-0 z-0 opacity-70 pointer-events-none">
          <ColorBends
            colors={['#FF3B3B', '#7A0000', '#3D0000']}
            rotation={90}
            speed={0.2}
            scale={1}
            frequency={1}
            warpStrength={1}
            mouseInfluence={1}
            parallax={0.5}
            noise={0.15}
            iterations={1}
            intensity={1.5}
            bandWidth={6}
            transparent
          />
        </div>
        <div className="relative z-10">{children}</div>
      </body>
    </html>
  )
}
